package run.ikaros.sharing; import java.time.Instant; import java.util.UUID; import org.springframework.stereotype.Service; import reactor.core.publisher.Mono; import run.ikaros.common.ConflictException; import run.ikaros.common.NotFoundException; @Service public class RoomControlService{private final RoomRepository rooms;private final RoomMembershipRepository members;private final RoomEventRepository events;public RoomControlService(RoomRepository r,RoomMembershipRepository m,RoomEventRepository e){rooms=r;members=m;events=e;}public Mono<RoomControlView> execute(UUID a,UUID id,ExecuteRoomControlCommandRequest q){return rooms.findById(id).switchIfEmpty(Mono.error(new NotFoundException("Room 不存在"))).flatMap(room->members.findByRoomIdAndPrincipalId(id,a).filter(m->m.leftAt()==null&&(m.role()==RoomRole.OWNER||m.role()==RoomRole.MODERATOR)).switchIfEmpty(Mono.error(new NotFoundException("无 Room Control 权限"))).thenReturn(room)).flatMap(room->{if(room.status()!=RoomStatus.ACTIVE)return Mono.error(new ConflictException("Room 当前不可控制"));if(q.expectedStateVersion()!=null&&q.expectedStateVersion()!=room.stateVersion())return Mono.error(new ConflictException("Room State Version 冲突"));long seq=room.sequence()+1,sv=room.stateVersion()+1;Instant now=Instant.now();return rooms.save(new RoomEntity(room.id(),room.ownerId(),room.kind(),room.targetType(),room.targetId(),room.visibility(),room.status(),sv,seq,room.expiresAt(),room.createdAt(),now,room.version())).then(events.save(new RoomEventEntity(null,id,seq,"room.control."+q.commandType(),a,now,q.payload(),sv))).map(e->new RoomControlView(e.eventId(),e.roomId(),e.sequence(),q.commandType(),e.actorId(),e.payload(),e.stateVersion(),e.occurredAt()));});}}
